import com.google.gson.annotations.JsonAdapter;
import org.junit.Test;

import java.lang.reflect.Type;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertFalse;

public class JsonAdapterNullSafeTest {

    /**
     * A deserializer that returns a default value when encountering JSON null.
     * This behavior is only accessible if nullSafe is set to false.
     */
    public static class DefaultOnNullDeserializer implements JsonDeserializer<String> {
        @Override
        public String deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) throws JsonParseException {
            if (json.isJsonNull()) {
                return "DEFAULT_VALUE";
            }
            return json.getAsString();
        }
    }

    /**
     * A serializer that writes a custom value when encountering Java null.
     * This behavior is only accessible if nullSafe is set to false.
     */
    public static class CustomNullSerializer implements JsonSerializer<String> {
        @Override
        public JsonElement serialize(String src, Type typeOfSrc, JsonSerializationContext context) {
            if (src == null) {
                return new JsonPrimitive("CUSTOM_NULL_VALUE");
            }
            return new JsonPrimitive(src);
        }
    }

    public static class ClassWithDeserializerNullSafeFalse {
        @JsonAdapter(value = DefaultOnNullDeserializer.class, nullSafe = false)
        String value;
    }

    public static class ClassWithDeserializerNullSafeTrue {
        @JsonAdapter(value = DefaultOnNullDeserializer.class, nullSafe = true)
        String value;
    }

    public static class ClassWithDeserializerNullSafeDefault {
        @JsonAdapter(value = DefaultOnNullDeserializer.class)
        String value;
    }

    public static class ClassWithSerializerNullSafeFalse {
        @JsonAdapter(value = CustomNullSerializer.class, nullSafe = false)
        String value;
    }

    @Test
    public void testDeserializerNullSafeFalse() {
        Gson gson = new Gson();
        String json = "{\"value\": null}";
        ClassWithDeserializerNullSafeFalse obj = gson.fromJson(json, ClassWithDeserializerNullSafeFalse.class);
        // Since nullSafe is false, the deserializer should be invoked with JsonNull
        // and return "DEFAULT_VALUE".
        assertEquals("DEFAULT_VALUE", obj.value);
    }

    @Test
    public void testDeserializerNullSafeTrue() {
        Gson gson = new Gson();
        String json = "{\"value\": null}";
        ClassWithDeserializerNullSafeTrue obj = gson.fromJson(json, ClassWithDeserializerNullSafeTrue.class);
        // Since nullSafe is true, Gson handles null and returns null without calling deserializer.
        assertNull(obj.value);
    }

    @Test
    public void testDeserializerNullSafeDefault() {
        Gson gson = new Gson();
        String json = "{\"value\": null}";
        ClassWithDeserializerNullSafeDefault obj = gson.fromJson(json, ClassWithDeserializerNullSafeDefault.class);
        // Default nullSafe is true.
        assertNull(obj.value);
    }

    @Test
    public void testSerializerNullSafeFalse() {
        Gson gson = new Gson();
        ClassWithSerializerNullSafeFalse obj = new ClassWithSerializerNullSafeFalse();
        obj.value = null;
        String json = gson.toJson(obj);
        // Since nullSafe is false, the serializer should be invoked with null
        // and produce "CUSTOM_NULL_VALUE".
        assertTrue(json.contains("\"value\":\"CUSTOM_NULL_VALUE\""));
        assertFalse(json.contains("\"value\":null"));
    }
}

