package com.google.gson.functional;

import com.google.gson.Gson;
import junit.framework.TestCase;

import java.util.Collection;
import java.util.Set;

/**
 * Test case for verifying correct resolution of type variables when they appear multiple times
 * in a generic class hierarchy. This relates to the fix in $Gson$Types.resolve method
 * where visited type variables are now mapped to their resolved types instead of just tracked in a set.
 */
public class TypeVariableResolutionTest extends TestCase {

    private enum TestEnum {
        ONE, TWO, THREE
    }

    private static class BaseCollection<U, C extends Collection<U>> {
        public C collection;
    }

    private static class SetCollection<T> extends BaseCollection<T, Set<T>> {
    }

    private static class TestEnumSetCollection extends SetCollection<TestEnum> {
    }

    public void testResolveRepeatedTypeVariable() {
        Gson gson = new Gson();
        String json = "{\"collection\":[\"ONE\",\"THREE\"]}";

        // This should not throw ClassCastException and should resolve T to TestEnum
        // Before the fix, the second encounter of TypeVariable T would return unresolved T,
        // causing elements to be deserialized as Strings instead of TestEnum.
        TestEnumSetCollection withSet = gson.fromJson(json, TestEnumSetCollection.class);

        assertNotNull("Deserialized object should not be null", withSet);
        assertNotNull("Collection field should not be null", withSet.collection);
        assertEquals("Collection should have 2 elements", 2, withSet.collection.size());

        for (Object item : withSet.collection) {
            assertTrue("Element should be TestEnum but was " + item.getClass().getName(), item instanceof TestEnum);
        }

        assertTrue("Collection should contain TestEnum.ONE", withSet.collection.contains(TestEnum.ONE));
        assertTrue("Collection should contain TestEnum.THREE", withSet.collection.contains(TestEnum.THREE));
    }
}

