import com.google.gson.Gson;
import com.google.gson.JsonDeserializationContext;
import com.google.gson.JsonDeserializer;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonParseException;
import com.google.gson.JsonPrimitive;
import com.google.gson.JsonSerializationContext;
import com.google.gson.JsonSerializer;
import com.google.gson.TypeAdapter;
import com.google.gson.annotations.JsonAdapter;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonWriter;
import org.junit.Test;

import java.io.IOException;
import java.lang.reflect.Type;

import static org.junit.Assert.*;

public class JsonAdapterNullSafeTest {

    // --- Deserializers ---

    // Deserializer for NullSafeFalseClass (nullSafe = false)
    // Should receive JsonNull and return a default object
    public static class NullSafeFalseClassDeserializer implements JsonDeserializer<NullSafeFalseClass> {
        @Override
        public NullSafeFalseClass deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) throws JsonParseException {
            if (json.isJsonNull()) {
                return new NullSafeFalseClass("default-from-null");
            }
            return new NullSafeFalseClass(json.getAsString());
        }
    }

    // Deserializer for NullSafeTrueClass (nullSafe = true)
    // Should NOT receive JsonNull (handled by TreeTypeAdapter)
    public static class NullSafeTrueClassDeserializer implements JsonDeserializer<NullSafeTrueClass> {
        @Override
        public NullSafeTrueClass deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) throws JsonParseException {
            // This should not be called with JsonNull if nullSafe=true
            if (json.isJsonNull()) {
                return new NullSafeTrueClass("unexpected-null-handled");
            }
            return new NullSafeTrueClass(json.getAsString());
        }
    }

    // Deserializer for DefaultNullSafeClass (default nullSafe = true)
    public static class DefaultNullSafeClassDeserializer implements JsonDeserializer<DefaultNullSafeClass> {
        @Override
        public DefaultNullSafeClass deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) throws JsonParseException {
            if (json.isJsonNull()) {
                return new DefaultNullSafeClass("unexpected-null-handled");
            }
            return new DefaultNullSafeClass(json.getAsString());
        }
    }

    // --- Serializers ---

    // Serializer for NullSafeFalseSerializerClass (nullSafe = false)
    // Should receive Java null and return a custom value
    public static class NullSafeFalseSerializerClassSerializer implements JsonSerializer<NullSafeFalseSerializerClass> {
        @Override
        public JsonElement serialize(NullSafeFalseSerializerClass src, Type typeOfSrc, JsonSerializationContext context) {
            if (src == null) {
                return new JsonPrimitive("null-transformed");
            }
            return new JsonPrimitive(src.getValue());
        }
    }

    // Serializer for NullSafeTrueSerializerClass (nullSafe = true)
    // Should NOT receive Java null (handled by TreeTypeAdapter)
    public static class NullSafeTrueSerializerClassSerializer implements JsonSerializer<NullSafeTrueSerializerClass> {
        @Override
        public JsonElement serialize(NullSafeTrueSerializerClass src, Type typeOfSrc, JsonSerializationContext context) {
            // This should not be called with null if nullSafe=true
            if (src == null) {
                return new JsonPrimitive("unexpected-null-handled");
            }
            return new JsonPrimitive(src.getValue());
        }
    }

    // --- TypeAdapter for coverage of TypeAdapter branch in getTypeAdapter ---

    public static class CustomTypeAdapter extends TypeAdapter<TypeAdapterClass> {
        @Override
        public void write(JsonWriter out, TypeAdapterClass value) throws IOException {
            if (value == null) {
                out.value("adapter-null-handled");
            } else {
                out.value(value.getValue());
            }
        }

        @Override
        public TypeAdapterClass read(JsonReader in) throws IOException {
            String str = in.nextString();
            if ("null-token".equals(str)) {
                return new TypeAdapterClass("adapter-default-from-null");
            }
            return new TypeAdapterClass(str);
        }
    }

    // --- Target Classes ---

    @JsonAdapter(value = NullSafeFalseClassDeserializer.class, nullSafe = false)
    public static class NullSafeFalseClass {
        private String value;
        public NullSafeFalseClass(String value) { this.value = value; }
        public String getValue() { return value; }
    }

    @JsonAdapter(value = NullSafeTrueClassDeserializer.class, nullSafe = true)
    public static class NullSafeTrueClass {
        private String value;
        public NullSafeTrueClass(String value) { this.value = value; }
        public String getValue() { return value; }
    }

    @JsonAdapter(value = DefaultNullSafeClassDeserializer.class)
    public static class DefaultNullSafeClass {
        private String value;
        public DefaultNullSafeClass(String value) { this.value = value; }
        public String getValue() { return value; }
    }

    @JsonAdapter(value = NullSafeFalseSerializerClassSerializer.class, nullSafe = false)
    public static class NullSafeFalseSerializerClass {
        private String value;
        public NullSafeFalseSerializerClass(String value) { this.value = value; }
        public String getValue() { return value; }
    }

    @JsonAdapter(value = NullSafeTrueSerializerClassSerializer.class, nullSafe = true)
    public static class NullSafeTrueSerializerClass {
        private String value;
        public NullSafeTrueSerializerClass(String value) { this.value = value; }
        public String getValue() { return value; }
    }

    @JsonAdapter(value = CustomTypeAdapter.class, nullSafe = false)
    public static class TypeAdapterClass {
        private String value;
        public TypeAdapterClass(String value) { this.value = value; }
        public String getValue() { return value; }
    }

    // --- Tests ---

    @Test
    public void testNullSafeFalse_DeserializerTransformsNull() {
        Gson gson = new Gson();
        // When nullSafe=false, deserializer should be called with JsonNull and can transform it
        NullSafeFalseClass result = gson.fromJson("null", NullSafeFalseClass.class);
        assertNotNull("Result should not be null when deserializer transforms null with nullSafe=false", result);
        assertEquals("default-from-null", result.getValue());
    }

    @Test
    public void testNullSafeTrue_DeserializerReturnsNull() {
        Gson gson = new Gson();
        // When nullSafe=true, deserializer should NOT be called with JsonNull
        NullSafeTrueClass result = gson.fromJson("null", NullSafeTrueClass.class);
        assertNull("Result should be null when nullSafe=true", result);
    }

    @Test
    public void testDefaultNullSafe_DeserializerReturnsNull() {
        Gson gson = new Gson();
        // Default nullSafe should be true
        DefaultNullSafeClass result = gson.fromJson("null", DefaultNullSafeClass.class);
        assertNull("Result should be null by default", result);
    }

    @Test
    public void testNullSafeFalse_SerializerTransformsNull() {
        Gson gson = new Gson();
        // When nullSafe=false, serializer should be called with null and can transform it
        NullSafeFalseSerializerClass obj = null;
        String json = gson.toJson(obj, NullSafeFalseSerializerClass.class);
        assertEquals("\"null-transformed\"", json);
    }

    @Test
    public void testNullSafeTrue_SerializerWritesNull() {
        Gson gson = new Gson();
        // When nullSafe=true, serializer should NOT be called with null
        NullSafeTrueSerializerClass obj = null;
        String json = gson.toJson(obj, NullSafeTrueSerializerClass.class);
        assertEquals("null", json);
    }

    @Test
    public void testNullSafeFalse_NonNullValue() {
        Gson gson = new Gson();
        NullSafeFalseClass result = gson.fromJson("\"test\"", NullSafeFalseClass.class);
        assertNotNull(result);
        assertEquals("test", result.getValue());
    }

    @Test
    public void testNullSafeTrue_NonNullValue() {
        Gson gson = new Gson();
        NullSafeTrueClass result = gson.fromJson("\"test\"", NullSafeTrueClass.class);
        assertNotNull(result);
        assertEquals("test", result.getValue());
    }

    @Test
    public void testNullSafeFalse_SerializerNonNullValue() {
        Gson gson = new Gson();
        NullSafeFalseSerializerClass obj = new NullSafeFalseSerializerClass("test");
        String json = gson.toJson(obj, NullSafeFalseSerializerClass.class);
        assertEquals("\"test\"", json);
    }

    @Test
    public void testNullSafeTrue_SerializerNonNullValue() {
        Gson gson = new Gson();
        NullSafeTrueSerializerClass obj = new NullSafeTrueSerializerClass("test");
        String json = gson.toJson(obj, NullSafeTrueSerializerClass.class);
        assertEquals("\"test\"", json);
    }

    // Additional test to cover TypeAdapter branch in getTypeAdapter
    @Test
    public void testTypeAdapter_NullSafeFalse() {
        Gson gson = new Gson();
        // Custom TypeAdapter with nullSafe=false should handle null itself
        // Note: JSON "null-token" is used to simulate null input for the adapter logic test
        // But for actual JSON null, if nullSafe=false, the adapter's read method is called.
        // However, JsonReader doesn't easily pass "null" as a string to nextString() without checking isNull().
        // To test nullSafe=false with TypeAdapter, we pass a value that the adapter treats specially.
        // More importantly, we test that nullSafe=false allows the adapter to be called.
        // If we pass "null-token", the adapter returns a default object.
        TypeAdapterClass result = gson.fromJson("\"null-token\"", TypeAdapterClass.class);
        assertNotNull(result);
        assertEquals("adapter-default-from-null", result.getValue());
    }

    // Test to ensure TypeAdapter with nullSafe=true wraps with nullSafe()
    // This requires a separate class with nullSafe=true
    @JsonAdapter(value = CustomTypeAdapter.class, nullSafe = true)
    public static class TypeAdapterNullSafeClass {
        private String value;
        public TypeAdapterNullSafeClass(String value) { this.value = value; }
        public String getValue() { return value; }
    }

    @Test
    public void testTypeAdapter_NullSafeTrue() {
        Gson gson = new Gson();
        // With nullSafe=true, Gson should handle JSON null before calling the adapter
        TypeAdapterNullSafeClass result = gson.fromJson("null", TypeAdapterNullSafeClass.class);
        assertNull("Result should be null when TypeAdapter is wrapped with nullSafe", result);
    }
}

