    @Test
    public void testTypeAdapter_NullSafeFalse() {
        Gson gson = new Gson();
        // Custom TypeAdapter with nullSafe=false should handle null itself
        // Note: JSON "null-token" is used to simulate null input for the adapter logic test
        // But for actual JSON null, if nullSafe=false, the adapter's read method is called.
        // However, JsonReader doesn't easily pass "null" as a string to nextString() without checking isNull().
